export function partsLib(o={}){const sets=[...Array(Math.max(...Object.values(VARIANTS).map(v=>v.length)))].map((_,i)=>Object.fromEntries(Object.entries(VARIANTS).filter(([,v])=>v[i]).map(([k,v])=>[k,v[i]]))),lods=[2,1,0].map(lv=>({lv,meshes:[],rings:{}}));let bones=null,nDeform=0;
  for(const VR of(o.only?sets.slice(0,o.only):sets)){const b=buildChao({variant:VR,levels:o.levels});bones=b.bones;nDeform=b.nDeform;b.lods.forEach(L=>{const D=lods.find(x=>x.lv===L.lv);for(const m of L.meshes){const sl=m.name.split('_')[0],sh=VR[sl];if(!sh||!(m.name===sl||m.name.startsWith(sl+'_')))continue;const nm=`${m.name}_${sh}`;D.meshes.push({...m,name:nm,slot:m.name,x:{shape:sh,part_slot:sl,...(PART_X[sl]?.[sh]||{})}});const r=L.rings[m.name];r&&(D.rings[nm]={...r,host:'core_none',key:m.name});}});}
  return{bones,nDeform,lods:lods.filter(L=>L.meshes.length)};}
