const qE=([x,y,z])=>{const r=Math.PI/360,[a,b,c]=[x*r,y*r,z*r],[sa,ca,sb,cb,sc,cc]=[Math.sin(a),Math.cos(a),Math.sin(b),Math.cos(b),Math.sin(c),Math.cos(c)];return[sa*cb*cc-ca*sb*sc,ca*sb*cc+sa*cb*sc,ca*cb*sc-sa*sb*cc,ca*cb*cc+sa*sb*sc];};
const kAt=(K,t)=>{if(t<=K[0][0])return K[0].slice(1);for(let i=1;i<K.length;i++)if(t<=K[i][0]){const u=ss((t-K[i-1][0])/(K[i][0]-K[i-1][0]||1));return K[i].slice(1).map((v,c)=>K[i-1][c+1]+(v-K[i-1][c+1])*u);}return K[K.length-1].slice(1);};
function clipAnims(CL,B,W,j0,A){const J=Object.fromEntries(B.map((b,i)=>[b.name,i])),rest=j=>B[j].parent>=0?W[j].map((v,c)=>v-W[B[j].parent][c]):W[j];
  return Object.entries(CL).map(([name,c])=>{const n=Math.round(c.len*30)+1,T=Float32Array.from({length:n},(_,i)=>i*c.len/(n-1)),ti=A(T,5126,'SCALAR',n,undefined,{min:[0],max:[c.len]}),samplers=[],channels=[],put=(j,path,v,w)=>{samplers.push({input:ti,output:A(v,5126,w,n),interpolation:'LINEAR'});channels.push({sampler:samplers.length-1,target:{node:j0+j,path}});};
    for(const[bn,K]of Object.entries(c.k||{}))J[bn]!==undefined&&put(J[bn],'rotation',Float32Array.from(Array.from(T).flatMap(t=>qE(kAt(K,t)))),'VEC4');
    for(const[bn,K]of Object.entries(c.loc||{}))J[bn]!==undefined&&put(J[bn],'translation',Float32Array.from(Array.from(T).flatMap(t=>kAt(K,t).map((v,i)=>v+rest(J[bn])[i]))),'VEC3');
    return{name,samplers,channels,extras:{loop:!!c.loop,in_place:true}};});}
